<?php
declare(strict_types=1);
final class AlertService {
 public static function sync(PDO $p,int $id):void{$lock=$p->prepare('SELECT id FROM items WHERE id=? FOR UPDATE');$lock->execute([$id]);if(!$lock->fetch())return;$s=$p->prepare('SELECT i.*,COALESCE(v.available_qty,0) available_qty,s.name supplier_name,s.email supplier_email,s.phone supplier_phone FROM items i LEFT JOIN v_item_availability v ON v.item_id=i.id LEFT JOIN suppliers s ON s.id=i.preferred_supplier_id WHERE i.id=?');$s->execute([$id]);$x=$s->fetch();if(!$x)return;$a=(int)$x['available_qty'];$r=(int)$x['reorder_level'];$q=$p->prepare("SELECT id,status FROM low_stock_alerts WHERE item_id=? AND status IN ('draft','sent') ORDER BY id DESC LIMIT 1 FOR UPDATE");$q->execute([$id]);$old=$q->fetch();if($a<$r){$subject="Low stock: {$x['name']} ({$x['sku']})";$body="Available: $a; reorder level: $r; suggested order: ".max(0,(int)$x['reorder_qty']-$a);$v=[ $subject,$body,$a,$r,max(0,(int)$x['reorder_qty']-$a),$x['supplier_name'],$x['supplier_email'],$x['supplier_phone']];if($old&&$old['status']==='draft'){$v[]=$old['id'];$p->prepare('UPDATE low_stock_alerts SET subject=?,body=?,available_qty=?,reorder_level=?,suggested_qty=?,supplier_name=?,supplier_email=?,supplier_phone=?,updated_at=NOW() WHERE id=?')->execute($v);}elseif(!$old)$p->prepare("INSERT INTO low_stock_alerts(item_id,status,subject,body,available_qty,reorder_level,suggested_qty,supplier_name,supplier_email,supplier_phone) VALUES(?,'draft',?,?,?,?,?,?,?,?)")->execute(array_merge([$id],$v));}elseif($old)$p->prepare("UPDATE low_stock_alerts SET status='resolved',resolved_at=NOW(),updated_at=NOW() WHERE id=?")->execute([$old['id']]);}
 public static function scan(PDO $p):int{$ids=$p->query('SELECT id FROM items WHERE is_active=1')->fetchAll(PDO::FETCH_COLUMN);foreach($ids as $id)self::sync($p,(int)$id);return count($ids);}
}
